From 25fde802a2a958f139501234f600fcb84c4bc7eb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:45:58 +0100
Subject: [PATCH] declarativeimports/core: float tooltips when the panel floats
 applets

Popups of applets in a panel that prefers floating applets keep a gap
from the panel, but tooltips stayed glued to it. Tooltips of such
applets now get the same margin as their popups.

BUG: 526985
---
 src/declarativeimports/core/tooltiparea.cpp | 18 ++++++++++++++++++
 1 file changed, 18 insertions(+)

diff --git a/src/declarativeimports/core/tooltiparea.cpp b/src/declarativeimports/core/tooltiparea.cpp
index 41e346e4c..a3b34c4f1 100644
--- a/src/declarativeimports/core/tooltiparea.cpp
+++ b/src/declarativeimports/core/tooltiparea.cpp
@@ -138,6 +138,22 @@ void ToolTipArea::showToolTip()
         }
     }

+    bool floatingApplet = false;
+    for (QQuickItem *p = parentItem(); p; p = p->parentItem()) {
+        PlasmaQuick::AppletQuickItem *appletItem = qobject_cast<PlasmaQuick::AppletQuickItem *>(p);
+        if (appletItem && (appletItem->applet()->containmentDisplayHints() & Plasma::Types::ContainmentPrefersFloatingApplets)) {
+            floatingApplet = true;
+            break;
+        }
+    }
+
+    int margin = 0;
+    if (floatingApplet && qmlEngine(this)) {
+        if (QObject *units = qmlEngine(this)->singletonInstance<QObject *>("org.kde.kirigami.platform", "Units")) {
+            margin = units->property("largeSpacing").toInt();
+        }
+    }
+
     if (mainItem()) {
         mainItem()->setProperty("toolTip", QVariant::fromValue(this));
         mainItem()->setVisible(true);
@@ -151,6 +167,8 @@ void ToolTipArea::showToolTip()
     dlg->setMainItem(mainItem());
     dlg->setInteractive(m_interactive);

+    dlg->setMargin(margin);
+
     switch (location) {
     case Plasma::Types::Floating:
     case Plasma::Types::Desktop:
-- 
